// A short original Web Audio flourish, respecting the game's existing mute setting.
export function evolutionAudio(context,offset=0){const master=context.createGain();master.gain.value=.18;master.connect(context.destination);const nodes=[],now=context.currentTime;
 const tone=(at,duration,hz,gain,type='sine')=>{if(at+duration<offset)return;duration=Math.min(duration,at+duration-offset);const start=now+Math.max(0,at-offset),o=context.createOscillator(),g=context.createGain();o.type=type;o.frequency.value=hz;g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(gain,start+.08);g.gain.exponentialRampToValueAtTime(.0001,start+duration);o.connect(g).connect(master);o.start(start);o.stop(start+duration+.02);nodes.push(o,g);};
 for(const hz of[196,293.665,391.995])tone(.1,3.7,hz,.07,'triangle');for(let i=0;i<18;i++)tone(1.05+i*.2,.38,[392,440,587.33,659.25,783.99,880][i%6]*2**Math.floor(i/12),.045);for(const[at,hz]of[[5.95,523.25],[6.09,659.25],[6.23,783.99],[6.38,1046.5]])tone(at,1.3,hz,.13);tone(6.52,.45,65.4,.2,'triangle');
 const length=Math.ceil(context.sampleRate*2.4),buffer=context.createBuffer(1,length,context.sampleRate),a=buffer.getChannelData(0);let seed=12;for(let i=0;i<a.length;i++){seed=(seed*1664525+1013904223)>>>0;a[i]=(seed/4294967296*2-1)*.25;}if(offset<4.6){const source=context.createBufferSource(),filter=context.createBiquadFilter(),g=context.createGain(),start=now+Math.max(0,2.2-offset);source.buffer=buffer;filter.type='bandpass';filter.frequency.setValueAtTime(250,start);filter.frequency.exponentialRampToValueAtTime(1900,start+2.3);g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(.12,start+.8);g.gain.linearRampToValueAtTime(0,start+2.4);source.connect(filter).connect(g).connect(master);source.start(start);nodes.push(source,filter,g);}return()=>{for(const n of nodes){try{n.stop?.();}catch{}n.disconnect();}master.disconnect();};}
